#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/code-lsp-check.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check that each LSP server of the selected tools resolves in the dev env"
# MISE tools={uv="latest", python="3.14"}

import json
import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def capture(cmd, env=None):
  """Run the command and return its stdout without the last newlines, or None
  when it fails. Its stderr goes nowhere."""
  try:
    result = subprocess.run(cmd, check=False, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
  except OSError:
    return None
  if result.returncode != 0:
    return None
  return result.stdout.rstrip("\n")


def text(value):
  """A value as the @tsv of jq writes it: null is empty."""
  if value is None:
    return ""
  if isinstance(value, str):
    return value
  return json.dumps(value)


def main():
  # BOOTSTRAP_BIN, a local build, replaces the bootstrap of mise. Without an
  # engine, the task stops with code 2: mise x answers a missing command with
  # code 1, the code of any other failure. Its header comes first, so the status
  # lines go under it.
  if os.environ.get("BOOTSTRAP_BIN", ""):
    binary = [os.environ["BOOTSTRAP_BIN"]]
  elif helpers.has_tool("bootstrap"):
    binary = ["mise", "x", "--", "bootstrap"]
  else:
    helpers.print_header("Checking the LSP servers ...")
    helpers.print_error("code:lsp:check needs bootstrap.")
    helpers.print_warn("- install it: mise use -g github:virajp/bootstrap", file=sys.stderr)
    return 2
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # The servers of the selected tools: only a tool in dev, and a source pin whose
  # requires_found is met. The engine prints its message and its fix on stderr.
  # Code 2 goes through as 2, any other failure is 1.
  try:
    result = subprocess.run([*binary, "lsp", "--json"], check=False, stdout=subprocess.PIPE, text=True)
    rc = result.returncode
  except OSError:
    rc = 1
  if rc:
    return 2 if rc == 2 else 1

  # data.checks gives the real command and the source of each server; the
  # entries of data.servers launch it through mise.
  try:
    data = json.loads(result.stdout).get("data")
    checks = (data.get("checks") if data is not None else None) or {}
    servers = [(name, text(entry.get("command")), text(entry.get("source"))) for name, entry in checks.items()]
  except (ValueError, AttributeError, TypeError):
    return 1

  # A repo without a server: the task does not apply and prints nothing.
  if not servers:
    return 0

  helpers.print_header("Checking the LSP servers ...")

  # Each check resolves a command and starts no server. A pinned server must be a
  # binary that mise manages in dev, never any binary on PATH; a host server comes
  # from Xcode.
  missing = 0
  dev = {**os.environ, "MISE_ENV": "dev"}
  for name, cmd, src in servers:
    if src == "host":
      path = capture(["xcrun", "--find", cmd])
      if path is not None:
        helpers.print_success(f"{name}: {path}")
      else:
        helpers.print_error(
          f"{name}: {cmd} not found - install the Xcode Command Line Tools (xcode-select --install) or Xcode"
        )
        missing = 1
      continue
    path = capture(["mise", "which", cmd], env=dev)
    if path is not None:
      helpers.print_success(f"{name}: {path}")
    else:
      helpers.print_error(f"{name}: {cmd} not found - run MISE_ENV=dev mise install")
      missing = 1

  return missing


if __name__ == "__main__":
  sys.exit(main())
